'use strict';
(function(){
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let songFilter='projects',occasionKey='',occasionState=null;
function status(x){if(x.archived)return x.scrapped?'Scrappée · conservée chez ses auteurs':'Archivée · droits des auteurs conservés';if(x.reworkPending)return 'Seconde version en écriture';if(x.reworkResult&&!x.adopted)return 'Seconde version · dernier essai';if(state.music.session?.songId===x.id)return state.music.session.kind==='trial'?'À l’essai au garage':'En répétition';if(M.ready(x))return 'Prête au show';if(x.adopted)return 'Au répertoire';if(x.votes.length)return 'À retravailler';return x.progress>=80?'À proposer au groupe':'En écriture';}
function reason(x){if(x.archived)return 'Cette chanson est conservée dans les archives personnelles de ses auteurs.';if(state.music.session)return 'Une séance se déroule déjà au garage.';if(x.progress<80)return 'La composition doit atteindre 80 %.';if(x.reworkPending)return 'Termine la seconde version à 100 % avant le dernier essai.';if(x.voteCount&&!x.reworkResult)return 'Après ce premier refus, une seule réécriture est disponible.';if(x.retryAt>state.tick)return 'Laisse passer un peu de temps avant de relancer une invitation.';return 'Inviter le groupe à essayer la chanson, puis recueillir son avis.';}
function actionButtons(x){if(x.archived)return '<p class="hint">'+(x.scrapped?'Scrappée :':'Deux refus :')+' retirée du collectif. La chanson reste dans le carnet personnel de ses auteurs et ne peut plus être proposée.</p>';return `<div class="song-card-actions">${!x.adopted?`<button data-trial="${x.id}" title="${esc(reason(x))}" ${!x.reworkPending&&(!x.voteCount||x.reworkResult)&&x.progress>=80&&x.lastVoteSignature!==M.signature(state,x)?'':'disabled'}>Essai au garage ↗</button>`:!M.ready(x)?`<button data-practice="${x.id}" >${state.music.session?'Planifier une répétition':'Proposer une répétition'}</button>`:'<span class="ready-label">✓ Prête pour la scène</span>'}<button class="quiet" data-details="${x.id}">Voir la chanson</button></div>`;}
function songCard(x){const key=M.ready(x)?'ready':state.music.session?.songId===x.id?'session':x.adopted?'adopted':x.votes.length?'rework':x.progress>=80?'trial':'writing';return `<article class="song-card status-${key}"><div class="song-authors">${x.authors.map(id=>{const p=state.people.find(p=>p.id===id);return p?`<span title="${esc(p.name)} · ${esc(p.instrument)}">${I.portrait(p)}</span>`:'';}).join('')}</div><div class="song-row-heading"><button class="song-title" data-details="${x.id}"><strong class="song-heading">${I.songTitle(x)}</strong><small>${esc(x.genre)} · ${esc(M.authors(state,x))}</small></button></div>${I.songStats(x)}<div class="song-state-line"><span class="song-status ${key}">${status(x)}</span>${!x.reworkPending&&(!x.voteCount||x.reworkResult)&&x.progress>=80&&!x.adopted&&x.lastVoteSignature!==M.signature(state,x)?`<button data-trial="${x.id}" class="song-next">Essayer ↗</button>`:x.adopted&&!M.ready(x)?`<button data-practice="${x.id}" class="song-next">Répéter ↗</button>`:''}</div><div class="song-bars"><div><span>Écriture <b>${Math.round(x.progress)} %</b></span><div class="song-meter"><i style="width:${x.progress}%"></i></div></div><div><span>Préparation <b>${x.adopted?x.preparation+' %':'—'}</b></span><div class="song-meter preparation"><i style="width:${x.adopted?x.preparation:0}%"></i></div></div></div>${!x.adopted&&(x.voteCount||M.canScrap(x))?reworkActions(x):''}</article>`;}
function revision(id){const result=D.submit(state,{type:'revise',songId:id});window.MaisonDecisionsUI.showOutcome(result);render();save();}
function scrapSong(id){const x=M.song(state,id);if(!M.canScrap(x))return;openDialog(`<span class="eyebrow">ABANDONNER CETTE CHANSON</span><h2>Scrapper la toune ?</h2>${I.context(state,{songId:id})}<p>Elle disparaîtra du répertoire collectif et du menu « À essayer ». Elle restera consultable dans la fiche de ses auteurs, mais ne pourra plus être proposée ni retravaillée.</p><div class="choice-row"><button id="confirmScrap" class="danger">Scrapper la toune</button><button id="cancelScrap">La garder</button></div>`);$('#confirmScrap').onclick=()=>{if(M.scrap(state,id)){save();closeDialog();render();toast('Chanson retirée du répertoire, conservée chez ses auteurs.');}else{toast('La chanson n’a pas été retirée : une séance est en cours ou elle n’est plus disponible.');}};$('#cancelScrap').onclick=()=>showSong(id);}
function reworkActions(x){return `<div class="song-rejection-actions">${M.canRevise(x)?`<button data-rework="${x.id}">↻ Proposer de retravailler</button>`:x.reworkPending?'<span>Réécriture en cours</span>':''}${M.canScrap(x)?`<button class="quiet danger" data-scrap="${x.id}" ${state.music.session?.songId===x.id?'disabled title="Attends la fin de l’essai en cours."':''}>Scrapper</button>`:''}</div>`;}
function bindSongs(container){container.querySelectorAll('[data-rework]').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;revision(b.dataset.rework);});container.querySelectorAll('[data-scrap]').forEach(b=>b.onclick=()=>{if(!b.disabled)scrapSong(b.dataset.scrap);});container.querySelectorAll('[data-trial]').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;trial(b.dataset.trial);});container.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;practice(b.dataset.practice);});container.querySelectorAll('[data-details]').forEach(b=>b.onclick=()=>showSong(b.dataset.details));}
function trial(id){const result=D.submit(state,{type:'trial',songId:id,title:'Essai de « '+M.song(state,id).title+' »'});window.MaisonDecisionsUI.showOutcome(result);render();save();}
function practice(id){const result=D.submit(state,{type:'practice',songId:id,title:'Répéter « '+M.song(state,id).title+' »'});window.MaisonDecisionsUI.showOutcome(result);render();save();}
function renderMusic(){M.reconcileOccasions(state);const pending=state.music.pending,banner=$('#storyBanner');banner.hidden=!pending.length;
// Keep the same DOM between simulation ticks so entrance effects never restart.
const key=pending.map(e=>e.id).join('|');if(key!==occasionKey||occasionState!==state){occasionKey=key;occasionState=state;
if(pending.length){const e=pending[0],p=state.people.find(p=>p.id===e.personId);banner.innerHTML=`<span class="occasion-cards" aria-hidden="true"><i></i><i></i><i>✦</i></span><div class="occasion-copy" role="status" aria-live="polite"><span class="eyebrow">✦ ${pending.length>1?pending.length+' CARTES À CHOISIR':'NOUVELLE CARTE DISPONIBLE'}</span><strong>${p?`${I.icons[p.instrument]||'♪'} ${esc(p.name)} peut enrichir son paquet`:'Une carte attend ton choix'}</strong></div><button class="primary occasion-cta" id="openStory">Choisir une carte <span aria-hidden="true">↗</span></button>`;$('#openStory').onclick=()=>showStory(e.id);}else banner.innerHTML='';}

const songScroll=$('#songCards').scrollTop;const songs=state.music.songs.filter(x=>!x.archived);$('#songMetrics').innerHTML=`<span><b>${songs.length}</b> chansons</span><span><b>${songs.filter(x=>x.adopted&&!M.ready(x)).length}</b> adoptées</span><span class="ready-metric"><b>${songs.filter(M.ready).length}</b> prêtes</span>`;const filtered=songs.filter(x=>songFilter==='projects'&&x.progress<100||songFilter==='trial'&&!x.adopted&&x.progress>=80||songFilter==='adopted'&&x.adopted&&!M.ready(x)||songFilter==='ready'&&M.ready(x));$('#songTotals').textContent=`${songs.length} chanson${songs.length>1?'s':''} · ${songs.filter(M.ready).length} prête${songs.filter(M.ready).length>1?'s':''}`;$('#songCards').innerHTML=filtered.length?filtered.slice().sort((a,b)=>Number(M.canTrial(state,b))-Number(M.canTrial(state,a))||b.created-a.created).map(songCard).join(''):'<div class="song-empty">'+(songFilter==='ready'?'Les chansons adoptées apparaîtront ici lorsqu’elles seront terminées et préparées à 100 %.':songFilter==='adopted'?'Aucune chanson adoptée à préparer. Les chansons terminées et maîtrisées se trouvent dans « Prêtes ».':'Aucune chanson dans cette catégorie pour le moment.')+'</div>';bindSongs($('#songCards'));$('#songCards').scrollTop=songScroll;$('#newComposition').disabled=false;
const session=state.music.session;$('#sessionStatus').hidden=!session;if(session){const x=M.song(state,session.songId);$('#sessionStatus').innerHTML=`${session.kind==='trial'?'Essai puis vote':'Répétition'} · ${I.songTitle(x)} · ${session.participants.length} participants · encore ${Math.max(0,session.ends-state.tick)*10} minutes de jeu.`;}
}
function showSong(id){const x=M.song(state,id);if(!x)return;const active=state.music.session?.songId===id;openDialog(`<span class="eyebrow">${esc(x.genre)} · ${status(x)}</span>${I.context(state,{songId:x.id},{people:true})}<div class="song-detail-stats"><div><b>${Math.round(x.progress)} %</b><span>Composition</span></div><div><b>${x.adopted?x.preparation+' %':'—'}</b><span>Préparation</span></div><div><b>${M.performance(x).level}/7</b><span>Qualité</span></div></div><p><strong>${M.qualityLabel(x.quality)}${x.reworkPending?' · réécriture en cours':''}</strong>. Budget ${M.performance(x).budget} = ${M.performance(x).turns} tours + ${M.performance(x).energyPerTurn} énergie par tour. ${x.archived?'Ces caractéristiques sont conservées avec la chanson; elle ne peut plus être retravaillée.':x.reworkPending?'Le résultat de la réécriture sera révélé à 100 %.':x.adopted?'Qualité verrouillée par l’adoption.':'Ces valeurs ne changent pas avec la simple écriture. Une réécriture après refus pourra les redistribuer.'} Préférence du style : ${M.performance(x).preferenceLabel.toLowerCase()}.</p><div class="hint">${active?'La séance se déroule au garage. Ferme cette fenêtre et relance le temps pour voir le résultat.':M.ready(x)?'Cette chanson est disponible dans BandLive au prochain show. Sa durée fixe le nombre de tours et son énergie par tour permet de jouer les cartes.':x.adopted?'La chanson est adoptée. Les auteurs peuvent finir de l’écrire pendant que le groupe se prépare. Une chanson longue demande davantage de répétitions. La préparation ne change ni sa durée ni son énergie par tour.':reason(x)}</div>${x.votes.length?`<h3 class="dialog-subtitle">Ce qu’en pense le groupe</h3><div class="votes">${x.votes.map(v=>I.response(state,v,{vote:true})).join('')}</div><p class="tiny">Adoption : plus de la moitié de tous les membres doivent être favorables. Les absents s’abstiennent.</p>`:''}<div class="choice-row">${M.canRevise(x)?`<button id="reviseSong">Proposer de retravailler</button>`:!x.archived&&x.progress<100&&(!x.voteCount||x.adopted||x.reworkPending)?`<button id="continueSong">Continuer l’écriture</button>`:''}</div>${M.canRevise(x)?'<p class="tiny">Les auteurs peuvent refuser pour le moment, puis changer d’avis. Une seule réécriture : +0 à +2 niveaux. Tours et énergie peuvent monter ou descendre, dans les limites. Le résultat sera comparé à 100 %.</p>':''}${!x.archived&&M.canScrap(x)?`<button class="quiet danger" data-scrap="${x.id}" ${active?'disabled title="Attends la fin de l’essai en cours."':''}>Scrapper la toune</button>`:''}${actionButtons(x)}`);bindSongs($('#dialogContent'));if($('#continueSong'))$('#continueSong').onclick=()=>{const result=D.submit(state,{type:'continue',songId:id});window.MaisonDecisionsUI.showOutcome(result);render();save();};if($('#reviseSong'))$('#reviseSong').onclick=()=>{const result=D.submit(state,{type:'revise',songId:id});window.MaisonDecisionsUI.showOutcome(result);render();save();};$('#dialogContent').querySelector('[data-details]')?.remove();}
function newComposition(){const available=state.people.filter(p=>!M.findProject(state,p));openDialog(`<span class="eyebrow">UNE PAGE BLANCHE</span><h2>Proposer une composition.</h2><p>Choisis un auteur pour un projet solo, ou plusieurs pour une composition collective. Chacun peut accepter ou préférer poursuivre sa journée.</p><div class="composer-options">${state.people.map(p=>`<label class="composer-option"><input type="checkbox" name="composer" value="${p.id}" >${avatar(p)}<span><strong>${p.name}</strong><small>${I.icons[p.instrument]||'♪'} ${p.instrument} · ${M.findProject(state,p)?'Projet en cours · invitation mise en attente':p.style+' · disponible'}</small></span></label>`).join('')}</div><label class="field-label" for="compositionGenre">Genre de la chanson</label><select id="compositionGenre" class="wide-select">${M.GENRES.map(g=>`<option value="${g}">${g} · tendance ${M.preferenceNames[M.stylePreferences[g]].toLowerCase()}</option>`).join('')}</select><div class="hint">Les auteurs gardent leurs projets personnels. Une composition commune partage les crédits et les contributions.</div><button class="primary" id="launchComposition" disabled>Proposer cette composition →</button>${!available.length?'<p>Tous les musiciens ont déjà un projet. Tu peux planifier cette nouvelle composition : l’invitation attendra qu’ils terminent leur écriture.</p>':''}`);document.querySelectorAll('[name=composer]').forEach(b=>b.onchange=()=>{$('#launchComposition').disabled=!document.querySelector('[name=composer]:checked');});$('#launchComposition').onclick=()=>{const ids=[...document.querySelectorAll('[name=composer]:checked')].map(x=>x.value),result=D.submit(state,{type:'compose',people:ids,genre:$('#compositionGenre').value});window.MaisonDecisionsUI.showOutcome(result);render();save();};}
function showStory(id){M.reconcileOccasions(state);const e=state.music.pending.find(x=>x.id===id);if(!e)return;if(e.type==='reward')return showCardReward(e);const choices=M.eventChoices(state,e);openDialog(`<span class="eyebrow">${e.type==='reward'?'UNE ÉVOLUTION DU PAQUET':'LA VIE DE LA MAISON'} · LE TEMPS EST EN PAUSE</span><h2>${esc(e.title)}</h2>${I.context(state,e,{people:true})}<p>${I.songText(state,e.body)}</p>${e.type==='reward'?'<div class="hint">Ces cartes sont conservées pour les futurs shows. Elles n’agissent pas sur la simulation de la maison. La taille du paquet évolue avec les récompenses.</div>':''}<div class="event-cards">${choices.map((c,i)=>{const gate=D.preflight(state,{type:c.id,eventType:e.type,songId:e.songId,personId:e.personId,people:e.people,genre:e.genre,slot:c.id.startsWith('card:')?0:undefined});return `<button class="event-card" data-choice="${c.id}"><span class="event-card-number">0${i+1}</span><strong>${esc(c.title)}</strong><p>${I.songText(state,c.text)}</p><span class="card-availability ${gate.status}">${c.id.startsWith('card:')?'Ajouter ou remplacer une carte':gate.status==='waiting'?'◷ En attente si choisie':gate.status==='blocked'?'Impossible dans cette situation':['inspire','rest','later','skip'].includes(c.id)?'Effet immédiat':'Disponible · réponse des musiciens à venir'}</span>${gate.status==='waiting'||gate.status==='blocked'?'<small>'+esc(gate.reason)+'</small>':''}<span class="event-card-arrow">${gate.status==='waiting'?'Mettre en attente':'Choisir'} ↗</span></button>`;}).join('')}</div><p class="tiny">Tu peux fermer cette fenêtre et décider plus tard. L’événement reste disponible.</p>`);let chosen=false;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(chosen||!state.music.pending.some(item=>item.id===e.id))return;chosen=true;if(b.dataset.choice.startsWith('card:'))return showCardReward(e);resolve(e,b.dataset.choice);});}
function resolve(e,choice,slot){const result=M.resolveEvent(state,e.id,choice,slot);if(!result){toast('Ce choix n’est plus disponible. Aucun effet n’a été appliqué.');return;}window.MaisonDecisionsUI.showOutcome(result);render();save();}
function showCardReward(e){
 const p=state.people.find(p=>p.id===e.personId);if(!p)return;
 const song=M.song(state,e.songId);const cards=M.eventChoices(state,e).filter(c=>c.id.startsWith('card:'));let selected=cards[0].id,locked=false;
 openDialog(`<div class="card-reward"><span class="eyebrow">${e.rewardSource==='adoption'?'RÉCOMPENSE D’ADOPTION':'ÉVOLUTION DU PAQUET'}</span><h2>${e.rewardMode==='replace'?'Une masterclasse pour':'Une nouvelle carte pour'} ${esc(p.name)}.</h2><div class="reward-context"><div class="reward-person">${I.portrait(p)}<span><strong>${I.icons[p.instrument]} ${esc(p.name)}</strong><small>${esc(p.instrument)} · ${p.deck.length} cartes</small></span></div>${song?`<div class="reward-song"><strong class="song-heading">${I.songTitle(song)}</strong>${I.songStats(song)}</div>`:''}</div><p>${e.rewardMode==='add'?'Ajoute une carte parmi les trois spéciales de son instrument.':e.rewardMode==='replace'?'Remplace une carte par une des trois spéciales de son instrument.':'Ajoute une carte ou remplace une carte de son paquet.'} <strong>${p.deck.length} cartes actuellement.</strong></p><div class="reward-cards" role="group" aria-label="Les trois cartes proposées">${cards.map((c,i)=>`<button class="reward-card ${i===0?'selected':''}" data-reward-card="${c.id}" aria-pressed="${i===0}"><span class="card-cost" title="Coût : ${c.cost} énergie" aria-label="Coût : ${c.cost} énergie">${c.cost}</span><strong>${esc(c.title)}</strong><p>${esc(c.text)}</p></button>`).join('')}</div><button id="toggleRewardDeck" class="quiet reward-deck-toggle" aria-expanded="false" aria-controls="rewardCurrentDeck">Voir mon paquet · ${p.deck.length} cartes</button><section id="rewardCurrentDeck" class="reward-current-deck" hidden><h3>Paquet actuel · ${p.deck.length} cartes</h3>${I.deck(p)}</section><div class="reward-controls"><label>Faire évoluer le paquet<select id="rewardMode">${e.rewardMode==='replace'?'':`<option value="add">Ajouter au paquet · ${p.deck.length+1} cartes</option>`}${e.rewardMode==='add'?'':`<option value="replace">Remplacer · ${p.deck.length} cartes</option>`}</select></label><label id="rewardSlotLabel" hidden>Carte à remplacer<select id="rewardSlot">${p.deck.map((id,i)=>`<option value="${i}">${i+1}. ${esc(M.CARDS[id].name)}</option>`).join('')}</select></label></div><p id="rewardPreview" class="hint" aria-live="polite"></p><div class="choice-row"><button class="primary" id="confirmReward">Ajouter la carte →</button><button class="quiet" id="skipReward">Ne pas prendre de carte</button></div><p class="tiny">Fermer conserve ce choix pour plus tard. Coûts payés avec l’énergie par tour de la chanson.</p></div>`);
 const update=()=>{const replace=$('#rewardMode').value==='replace';$('#rewardSlotLabel').hidden=!replace;$('#confirmReward').textContent=replace?'Confirmer le remplacement →':'Ajouter la carte →';const card=M.CARDS[selected.slice(5)],old=M.CARDS[p.deck[Number($('#rewardSlot').value)]];$('#rewardPreview').textContent=replace?`${old.name} → ${card.name} · ${p.deck.length} cartes`:`${card.name} rejoint le paquet · ${p.deck.length} → ${p.deck.length+1} cartes`;};
 document.querySelectorAll('[data-reward-card]').forEach(b=>b.onclick=()=>{selected=b.dataset.rewardCard;document.querySelectorAll('[data-reward-card]').forEach(el=>{const active=el===b;el.classList.toggle('selected',active);el.setAttribute('aria-pressed',String(active));});update();});
 $('#toggleRewardDeck').onclick=()=>{const panel=$('#rewardCurrentDeck');panel.hidden=!panel.hidden;$('#toggleRewardDeck').setAttribute('aria-expanded',String(!panel.hidden));$('#toggleRewardDeck').textContent=panel.hidden?`Voir mon paquet · ${p.deck.length} cartes`:'Masquer mon paquet';};
 $('#rewardMode').onchange=update;$('#rewardSlot').onchange=update;
 $('#confirmReward').onclick=()=>{if(locked)return;locked=true;resolve(e,selected,$('#rewardMode').value==='add'?'add':Number($('#rewardSlot').value));};
 $('#skipReward').onclick=()=>{if(locked)return;locked=true;resolve(e,'skip');};$('#rewardMode').value=e.rewardMode==='replace'?'replace':'add';update();
}

function showDeck(id){const p=state.people.find(p=>p.id===id);openDialog(`<span class="eyebrow">${p.deck.length} CARTES · ${esc(p.instrument).toUpperCase()}</span><h2>Le paquet de ${esc(p.name)}.</h2>${I.context(state,{personId:p.id},{people:true})}<p>Toutes ses cartes rejoignent la pioche commune du concert. Les événements permettent d’en ajouter ou d’en remplacer.</p>${I.deck(p)}<p class="hint">${I.stageEnergy(p)}</p>`);}

$('#newComposition').onclick=newComposition;document.querySelectorAll('[data-song-filter]').forEach(b=>b.onclick=()=>{songFilter=b.dataset.songFilter;document.querySelectorAll('[data-song-filter]').forEach(x=>x.classList.toggle('active',x===b));renderMusic();});window.MaisonMusicUI={render:renderMusic,showStory,showDeck,showSong,resetView:()=>{songFilter='projects';document.querySelectorAll('[data-song-filter]').forEach(b=>b.classList.toggle('active',b.dataset.songFilter==='projects'));}};renderMusic();
})();
